        self,
        messages: list[dict],
        *,
        add_generation_prompt: bool = False,
        add_eos: bool = True,
    ) -> list[int]:
        ids: list[int] = [self.bos_id]
        role_tokens = {
            "system": ("<system>", "</system>"),
            "user": ("<user>", "</user>"),
            "assistant": ("<assistant>", "</assistant>"),
