        re.match(r"^\s*(what|who)\s+is\b", work, re.I)
        and not re.search(r"\b(create|make|build|implement)\b", work, re.I)
    )
    if definitional:
        state.intent = "knowledge"
        if not state.plan:
            state.plan = [
