        if not state.plan:
            state.plan = [
                "Retrieve knowledge/memory",
                "Reason and verify",
                "Answer clearly",
            ]
    elif not state.plan:
        state.plan = [
            "Understand meaning",
            "Use memory + knowledge if relevant",
            "Reply naturally",
        ]
    return state


