def _parse_key_list(raw_env: str, *, default_role: str) -> dict[str, str]:
    """Parse comma-separated ``key`` or ``key:role`` entries into a key→role map."""
    keys: dict[str, str] = {}
    if not raw_env.strip():
        return keys
    fallback = default_role if default_role in VALID_ROLES else "viewer"
    for raw in raw_env.split(","):
        raw = raw.strip()
        if not raw:
            continue
        if ":" in raw:
            k, _, role = raw.partition(":")
            role = role.strip() if role.strip() in VALID_ROLES else fallback
            key = k.strip()
            if key:
                keys[key] = role
        else:
            keys[raw] = fallback
    return keys


def _load_api_keys() -> dict[str, str]:
    keys: dict[str, str] = {}
    # Standard bootstrap: key or key:role (bare key → operator).
    keys.update(_parse_key_list(os.getenv("OM_AI_API_KEYS", ""), default_role="operator"))
    # Optional admin-only list (bare key → admin). Supported so .env can keep
    # OM_AI_API_KEYS_ADMIN=…:admin without merging into OM_AI_API_KEYS.
    keys.update(_parse_key_list(os.getenv("OM_AI_API_KEYS_ADMIN", ""), default_role="admin"))
    keys_file = os.getenv("OM_AI_API_KEYS_FILE", "").strip()
    if keys_file and os.path.isfile(keys_file):
        with open(keys_file) as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            for k, role in data.items():
                keys[str(k)] = role if role in VALID_ROLES else "viewer"
    return keys


class APIKeyAuth:
    def __init__(self) -> None:
        self._keys: dict[str, str] = {}
        self._dev_mode: bool = False
        self.reload()

    def reload(self) -> None:
        self._keys = _load_api_keys()
        if not self._keys:
            # DB tokens alone are enough — don't force open/dev mode if tokens DB may have keys
            try:
                from om_ai.security.tokens import get_token_store
                if get_token_store().list():
                    self._dev_mode = False
                    return
            except Exception:
                pass
            if os.getenv("OM_AI_REQUIRE_AUTH", "0") == "1":
                warnings.warn(
                    "OM_AI_REQUIRE_AUTH=1 but no keys configured – all requests will be rejected.",
                    stacklevel=2,
                )
                self._dev_mode = False
            else:
                warnings.warn(
                    "No API keys configured – running in dev mode. "
                    "Set OM_AI_API_KEYS or create a token via POST /v1/tokens.",
                    stacklevel=2,
                )
                self._dev_mode = True
        else:
            self._dev_mode = False

    def validate(self, key: str) -> Optional[str]:
        """Return role for env key, or None. DB tokens validated separately."""

