                    for net in _BLOCKED_NETS:
                        if resolved in net:
                            raise SSRFError(f"Host {host!r} resolves to blocked address {addr_str}")
                except ValueError:
                    pass

        def safe_url(self, url: str) -> str:
            self.check_url(url)
            return url


