class KnowledgeSearchTool(Tool):
    """Search the knowledge base for relevant documents."""

    name = "knowledge.search"
    description = (
        "Search the private knowledge base for relevant context. "
        "Returns matching text chunks with metadata."
    )
    risk_level = "low"
    input_schema = {
        "type": "object",
        "properties": {
            "query": {"type": "string"},
            "k": {"type": "integer"},
        },
        "required": ["query"],
    }

    def __init__(self, knowledge_base: Any, default_k: int = 5, tenant_id: str = "default") -> None:
        self._kb = knowledge_base
        self._default_k = default_k
        self._tenant_id = tenant_id

    def run(self, query: str = "", k: int | None = None, tenant_id: str | None = None, **kwargs: Any) -> ToolResult:
        q = query or kwargs.get("q") or ""
        if not q:
            return ToolResult(False, error="query is required")
        top_k = k if k is not None else self._default_k
        tid = tenant_id or self._tenant_id
        try:
            if hasattr(self._kb, "search_compat"):
                results = self._kb.search_compat(q, k=top_k, tenant_id=tid)
            else:
                # PersistentKnowledgeBase.search(query, tenant_id, k=...)
                try:
                    results = self._kb.search(q, tid, k=top_k)
                except TypeError:
                    results = self._kb.search(q, top_k)
            snippets = []
            for r in results or []:
                if hasattr(r, "text"):
                    snippets.append({
                        "text": r.text,
                        "doc_id": getattr(r, "doc_id", None),
                        "score": getattr(r, "score", None),
                        "tenant_id": getattr(r, "tenant_id", tid),
                    })
                elif isinstance(r, dict):
                    snippets.append(r)
                else:
                    snippets.append({"text": str(r)})
            return ToolResult(ok=True, data=snippets)
        except Exception as exc:
            logger.warning("KnowledgeSearchTool error: %s", exc)
            return ToolResult(ok=False, error=str(exc))

"""Detect weak areas from evaluation scores."""
from __future__ import annotations

from typing import Any


THRESHOLDS = {
    "structure": 70.0,
    "clarity": 65.0,
    "security": 70.0,
    "task_fit": 65.0,
    "code_quality": 70.0,
}


def detect_weaknesses(eval_result: dict[str, Any]) -> list[dict[str, Any]]:
    scores = eval_result.get("scores") or {}
    weak: list[dict[str, Any]] = []
    for key, thr in THRESHOLDS.items():
        val = float(scores.get(key, 100.0))
        if val < thr:
            weak.append(
                {
                    "area": key,
                    "score": val,
                    "threshold": thr,
                    "hint": _hint(key),
                }
            )
    if float(eval_result.get("overall") or 0) < 70:
        weak.append(
            {
                "area": "overall",
                "score": float(eval_result.get("overall") or 0),
                "threshold": 70.0,
                "hint": "Improve completeness and directness of the answer",
            }
        )
    # dedupe by area
    seen: set[str] = set()
    out: list[dict[str, Any]] = []
    for w in weak:
        if w["area"] in seen:
            continue
        seen.add(w["area"])
        out.append(w)
    return out


def _hint(area: str) -> str:
    return {
        "structure": "Use clear sections: Understanding, Plan, Implementation, Validation",
        "clarity": "Write shorter clear sentences; avoid garbled fragments",
        "security": "Include validation, no secrets, safe auth patterns",
        "task_fit": "Address every part of the user ask explicitly",
        "code_quality": "Include runnable code blocks and tests",
    }.get(area, "Improve this dimension")

