"""Local lexical search (BM25-lite) — no external embeddings / no LLM."""
from __future__ import annotations

import math
import re
from collections import Counter
from dataclasses import dataclass
from pathlib import Path


_TOKEN = re.compile(r"[a-z0-9][a-z0-9_\-]{1,}", re.IGNORECASE)


@dataclass(frozen=True)
class SearchHit:
    doc_id: str
    score: float
    snippet: str
    source: str = "local"


def _tokens(text: str) -> list[str]:
    return [t.lower() for t in _TOKEN.findall(text or "")]


class LocalSearchIndex:
    """In-memory BM25-lite keyword index — not an LLM ranker."""

    def __init__(self, *, k1: float = 1.5, b: float = 0.75) -> None:
        self._docs: dict[str, str] = {}
        self._sources: dict[str, str] = {}
        self._tf: dict[str, Counter[str]] = {}
        self._df: Counter[str] = Counter()
        self._dl: dict[str, int] = {}
        self._k1 = k1
        self._b = b

    def add(self, doc_id: str, text: str, *, source: str = "local") -> None:
        if doc_id in self._docs:
            self.remove(doc_id)
        toks = _tokens(text)
        self._docs[doc_id] = text
        self._sources[doc_id] = source
        self._tf[doc_id] = Counter(toks)
        self._dl[doc_id] = max(1, len(toks))
        for term in set(toks):
            self._df[term] += 1

    def remove(self, doc_id: str) -> None:
        if doc_id not in self._docs:
            return
        for term in set(self._tf[doc_id]):
            self._df[term] -= 1
            if self._df[term] <= 0:
                del self._df[term]
        del self._docs[doc_id]
        del self._sources[doc_id]
        del self._tf[doc_id]
        del self._dl[doc_id]

    @property
    def size(self) -> int:
        return len(self._docs)

    def _avgdl(self) -> float:
        if not self._dl:
            return 1.0
        return sum(self._dl.values()) / len(self._dl)

    def search(self, query: str, *, limit: int = 5) -> list[SearchHit]:
        q_terms = _tokens(query)
        if not q_terms or not self._docs:
            return []
        n = len(self._docs)
        avgdl = self._avgdl()
        scores: dict[str, float] = {}
        for doc_id, tf in self._tf.items():
            score = 0.0
            dl = self._dl[doc_id]
            for term in q_terms:
                if term not in tf:
                    continue
                df = self._df.get(term, 0)
                idf = math.log(1.0 + (n - df + 0.5) / (df + 0.5))
                f = tf[term]
                denom = f + self._k1 * (1.0 - self._b + self._b * dl / avgdl)
                score += idf * (f * (self._k1 + 1.0)) / denom
            if score > 0:
                scores[doc_id] = score
        ranked = sorted(scores.items(), key=lambda x: x[1], reverse=True)[:limit]
        hits: list[SearchHit] = []
        for doc_id, score in ranked:
            text = self._docs[doc_id]
            snippet = text[:280].replace("\n", " ").strip()
            hits.append(
                SearchHit(
                    doc_id=doc_id,
                    score=round(score, 4),
                    snippet=snippet,
                    source=self._sources.get(doc_id, "local"),
                )
            )
        return hits


def index_text_files(
    root: str | Path,
    *,
    index: LocalSearchIndex | None = None,
    patterns: tuple[str, ...] = ("*.md", "*.txt", "*.rst"),
    max_files: int = 200,
    max_chars: int = 8000,
) -> LocalSearchIndex:
    """Load local docs into a lexical index."""
    idx = index or LocalSearchIndex()
    root_path = Path(root)
    if not root_path.is_dir():
        return idx
    count = 0
    for pattern in patterns:
        for path in sorted(root_path.rglob(pattern)):
            if not path.is_file():
                continue
            try:
                text = path.read_text(encoding="utf-8", errors="ignore")[:max_chars]
            except OSError:
                continue
            if not text.strip():
                continue
            rel = str(path.relative_to(root_path))
            idx.add(rel, text, source=f"local:{root_path.name}")
            count += 1
            if count >= max_files:
                return idx
    return idx

"""Authorized single-host document fetch for live-knowledge ingestion.

This is not a general web spider. It fetches one approved URL (or a short
same-host link expansion) with SSRF protections. Mass scraping of third-party
sites is intentionally out of scope.
"""
from __future__ import annotations

import ipaddress
import re
import socket
from dataclasses import dataclass
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlparse
from urllib.request import Request, urlopen


@dataclass(frozen=True)
class CrawlPage:
    url: str
    text: str
    status: int = 200
    stub: bool = False


class _TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self._chunks: list[str] = []
        self._skip = False

    def handle_starttag(self, tag, attrs):
        if tag in {"script", "style", "noscript"}:
            self._skip = True

    def handle_endtag(self, tag):
        if tag in {"script", "style", "noscript"}:
            self._skip = False

    def handle_data(self, data):
        if not self._skip:
            t = data.strip()
            if t:
                self._chunks.append(t)

    def text(self) -> str:
        return "\n".join(self._chunks)


_HREF_RE = re.compile(r'href=["\']([^"\']+)["\']', re.I)


def _is_public_host(hostname: str) -> bool:
    if not hostname or hostname.lower() in {"localhost"}:
        return False
    try:
        infos = socket.getaddrinfo(hostname, None)
    except socket.gaierror:
        return False
    for info in infos:
        ip = ipaddress.ip_address(info[4][0])
        if (
            ip.is_private
            or ip.is_loopback
            or ip.is_link_local
            or ip.is_reserved
            or ip.is_multicast
        ):
            return False
    return True


def _fetch(url: str, *, timeout: float = 10.0) -> tuple[int, str, str]:
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"}:
        raise ValueError(f"unsupported scheme: {parsed.scheme}")
    if not _is_public_host(parsed.hostname or ""):
        raise ValueError("refusing non-public or unresolved host (SSRF guard)")
    req = Request(
        url,
        headers={"User-Agent": "OM-AI-Operating-Brain/0.3 (+authorized-fetch)"},
        method="GET",
    )
    with urlopen(req, timeout=timeout) as resp:  # noqa: S310 — scheme/host gated above
        raw = resp.read(2_000_000)
        ctype = (resp.headers.get("Content-Type") or "").lower()
        status = getattr(resp, "status", 200) or 200
        charset = "utf-8"
        if "charset=" in ctype:
            charset = ctype.split("charset=", 1)[1].split(";")[0].strip() or "utf-8"
        text = raw.decode(charset, errors="replace")
        return int(status), ctype, text


def _html_to_text(html: str) -> str:
    p = _TextExtractor()
    try:
        p.feed(html)
    except Exception:
        return re.sub(r"<[^>]+>", " ", html)
    return p.text()


def crawl(
    seed_url: str,
    *,
    max_pages: int = 1,
    same_host_only: bool = True,
    timeout: float = 10.0,
) -> list[CrawlPage]:
    """Fetch ``seed_url`` and optionally a few same-host links from that page."""
    pages: list[CrawlPage] = []
    seen: set[str] = set()
    queue = [seed_url]
    seed_host = urlparse(seed_url).netloc

    while queue and len(pages) < max(1, max_pages):
        url = queue.pop(0)
        if url in seen:
            continue
        seen.add(url)
        try:
            status, ctype, body = _fetch(url, timeout=timeout)
        except (ValueError, HTTPError, URLError, TimeoutError, OSError) as exc:
            pages.append(
                CrawlPage(url=url, text=f"[OM crawler] fetch failed: {exc}", status=0, stub=False)
            )
            continue
        if "html" in ctype or body.lstrip().startswith("<"):
            text = _html_to_text(body)
            if same_host_only and len(pages) + len(queue) < max_pages:
                for href in _HREF_RE.findall(body)[:50]:
                    abs_url = urljoin(url, href.split("#", 1)[0])
                    if urlparse(abs_url).netloc != seed_host:
                        continue
                    if abs_url not in seen:
                        queue.append(abs_url)
        else:
            text = body[:200_000]
        pages.append(CrawlPage(url=url, text=text, status=status, stub=False))
    return pages


def crawl_stub(seed_url: str, *, max_pages: int = 1) -> list[CrawlPage]:
    """Backward-compatible alias — now performs a real guarded fetch."""
    return crawl(seed_url, max_pages=max_pages)

