"""
OM Task Dependency Graph
"""




class DependencyGraph:



    def build(

        self,

        tasks

    ):


        graph={}



        for task in tasks:


            graph[task.id]=task.depends_on



        return graph




    def ready_tasks(

        self,

        tasks

    ):


        completed={

            t.id

            for t in tasks

            if t.status=="completed"

        }



        return [

            t

            for t in tasks

            if t.status=="pending"

            and all(

                x in completed

                for x in t.depends_on

            )

        ]

"""
OM Autonomous Task Executor
"""


from om_ai.collaboration import AgentCoordinator

class TaskExecutor:



    def __init__(

        self,

        agent_executor=None

    ):


        self.agent_executor=agent_executor
        self.coordinator = AgentCoordinator()




    def execute(

        self,

        task,

        context=None

    ):


        context=context or {}

        self.coordinator.collaborate(

            task.to_dict(),

            [

                task.agent

            ]

        )

        if self.agent_executor:


            result=self.agent_executor.execute(

                {

                    "name":
                        task.agent,

                    "agent":
                        task.agent

                },

                task.description,

                context

            )


        else:


            result={

                "message":

                "No execution engine connected"

            }



        task.complete(

            result

        )


        return task

