"""Agent civilization bridge — route to specialist agent roles."""
from __future__ import annotations

from typing import Any

_ROUTES = {
    "coding": "coding",
    "debug": "coding",
    "performance": "coding",
    "knowledge": "research",
    "agent": "master",
    "security": "security",
    "chat": "master",
}


def select_agents(intent: str, text: str = "") -> list[str]:
    t = (text or "").lower()
    agents = [_ROUTES.get(intent, "master")]
    if any(w in t for w in ("security", "auth", "vuln", "secret", "login")):
        agents.append("security")
    if any(w in t for w in ("deploy", "docker", "k8s", "ci", "production")):
        agents.append("deployment")
    if any(w in t for w in ("test", "pytest", "jest", "qa")):
        agents.append("testing")
    if any(w in t for w in ("sql", "schema", "postgres", "mysql", "mongo", "database")):
        agents.append("database")
    if any(w in t for w in ("robot", "motor", "gpio", "esp32", "sensor")):
        agents.append("hardware")
    seen: set[str] = set()
    out: list[str] = []
    for a in agents:
        if a not in seen:
            seen.add(a)
            out.append(a)
    return out


def run_agents(goal: str, *, intent: str, agents: list[str], snippets: list[str] | None = None) -> dict[str, Any]:
    from om_ai.agents.specialists import run_specialists

    result = run_specialists(goal, agents=agents, snippets=snippets)
    notes = []
    try:
        from om_ai.agents.roles import ROLES

        for name in result.get("agents") or agents:
            role = ROLES.get(name)
            notes.append(f"{name}: {role.description}" if role else f"{name}: routed")
    except Exception:
        notes = [f"{a}: routed" for a in agents]
    result["notes"] = notes
    result["intent"] = intent
    return result

"""Memory bridge — multi-layer human-like memory for Absolute OS."""
from __future__ import annotations

from typing import Any


def recall_all(
    query: str,
    *,
    tenant_id: str = "default",
    user_id: str = "",
    project_id: str | None = None,
    k: int = 4,
) -> dict[str, Any]:
    out: dict[str, Any] = {
        "short_term": [],
        "conversation": [],
        "user": [],
        "project": [],
        "skill": [],
        "experience": [],
        "knowledge": [],
    }
    actor = user_id or ""
    # UI / chat memories
    try:
        from om_ai.agent.tools import recall_memory, search_knowledge

        out["conversation"] = recall_memory(
            query, tenant_id=tenant_id, actor=actor, project_id=project_id, limit=k
        )
        out["knowledge"] = search_knowledge(query, tenant_id=tenant_id, k=k)
    except Exception:
        pass

    # Layered memory store
    if actor:
        try:
            from om_ai.memory.layers import LayeredMemory

            mem = LayeredMemory(tenant_id=tenant_id, user_id=actor)
            for layer in ("user", "project", "skill", "experience", "short", "conversation"):
                hits = mem.recall(query, layer=layer, k=max(2, k // 2)) or []
                key = "short_term" if layer == "short" else layer
                for h in hits:
                    text = str(h.get("content") or h.get("text") or "").strip()
                    if text:
                        out[key].append(text[:240])
        except Exception:
            pass

    # Dataset brain as knowledge memory
    try:
        from om_ai.brain.dataset_engine import retrieve_answer

        hit = retrieve_answer(query)
        if hit and hit.get("answer"):
            out["knowledge"].insert(0, str(hit["answer"])[:900])
    except Exception:
        pass

    return out


def remember_experience(
    content: str,
    *,
    tenant_id: str = "default",
    user_id: str = "",
    layer: str = "experience",
) -> dict[str, Any]:
    if not user_id or not content.strip():
        return {"ok": False, "reason": "missing_user_or_content"}
    try:
        from om_ai.memory.layers import LayeredMemory

        mid = LayeredMemory(tenant_id=tenant_id, user_id=user_id).remember(
            layer if layer else "experience", content.strip()
        )
        return {"ok": True, "id": mid, "layer": layer}
    except Exception as exc:
        return {"ok": False, "error": str(exc)}

"""Knowledge bridge — RAG + dataset brain + fact table + vector index."""
from __future__ import annotations

import logging
from typing import Any

logger = logging.getLogger(__name__)


def research(query: str, *, tenant_id: str = "default", k: int = 6) -> dict[str, Any]:
    snippets: list[str] = []
    source = "none"
    grounded = ""
    extra: dict[str, Any] = {}

    try:
        from om_ai.knowledge.facts import lookup_fact

        fact = lookup_fact(query)
        if fact and fact.get("answer"):
            grounded = str(fact["answer"])
            snippets.append(grounded[:900])
            source = "fact_table"
            extra["entities"] = fact.get("entities") or {}
            extra["fact_id"] = fact.get("id")
            try:
                from om_ai.knowledge.embeddings import EmbeddingIndex

                EmbeddingIndex().upsert(
                    grounded,
                    tenant_id=tenant_id,
                    metadata={"domain": fact.get("domain") or "civics", "id": fact.get("id")},
                    doc_id=str(fact.get("id") or "fact"),
                )
            except Exception as exc:
                logger.debug("fact embed upsert skipped: %s", exc)
    except Exception as exc:
        logger.debug("fact lookup skipped: %s", exc)

    try:
        from om_ai.brain.dataset_engine import retrieve_answer

        hit = retrieve_answer(query)
        if hit and hit.get("answer"):
            ans = str(hit["answer"])
            if not grounded:
                grounded = ans
            if ans not in snippets:
                snippets.append(ans[:900])
            if source == "none":
                source = "dataset_brain"
    except Exception:
        pass

    try:
        from om_ai.knowledge.retrieval import VectorKnowledgeLayer

        for row in VectorKnowledgeLayer(tenant_id=tenant_id).search(query, k=k) or []:
            text = str(row.get("text") or "")
            if text and text not in snippets:
                snippets.append(text[:400])
        if source == "none" and snippets:
            source = "vector"
    except Exception:
        try:
            from om_ai.agent.tools import search_knowledge

            for s in search_knowledge(query, tenant_id=tenant_id, k=k) or []:
                if s and s not in snippets:
                    snippets.append(s[:400])
            if source == "none" and snippets:
                source = "rag"
        except Exception:
            pass

    try:
        from om_ai.knowledge.selector import select_knowledge

        profile = select_knowledge(query, snippets)
        snippets = profile.kept or snippets
        extra.update(
            {
                "important": profile.important,
                "not_important": profile.not_important,
                "dropped": profile.dropped,
                "topic": profile.topic,
            }
        )
    except Exception:
        extra.setdefault("dropped", [])

    try:
        from om_ai.knowledge.ranker import detect_domain, rank_sources

        ranked = rank_sources(query, snippets)
        extra["domain"] = ranked.domain or detect_domain(query)
        extra["ranked"] = ranked.to_dict()
        if ranked.ranked:
            snippets = [r.text for r in ranked.ranked]
        extra["dropped"] = list(extra.get("dropped") or []) + ranked.dropped
    except Exception:
        extra.setdefault("domain", "general")

    return {
        "snippets": snippets[:k],
        "grounded_reply": grounded,
        "source": source,
        "count": len(snippets),
        **extra,
    }

