"""
OM Quality Checker

Evaluates generated results.
"""


from __future__ import annotations




class QualityChecker:



    def evaluate(

        self,

        result:str

    ) -> dict:



        score = 0.0


        issues=[]



        if result:

            score += 0.4


        else:

            issues.append(
                "empty response"
            )



        if len(result) > 100:

            score +=0.2


        else:

            issues.append(
                "response too short"
            )



        if "solution" in result.lower():

            score +=0.2



        if "error" not in result.lower():

            score +=0.2



        return {


            "score":

                round(score,2),


            "approved":

                score >=0.7,


            "issues":

                issues

        }

"""
OM Self Correction Loop
"""


from .quality_checker import QualityChecker

from .correction import CorrectionPlanner





class SelfCorrectionLoop:



    def __init__(self):


        self.checker = QualityChecker()

        self.corrector = CorrectionPlanner()




    def review(

        self,

        result:str

    ):


        evaluation = self.checker.evaluate(

            result

        )



        if evaluation["approved"]:


            return {


                "approved":

                    True,


                "evaluation":

                    evaluation,


                "actions":[]

            }




        actions = self.corrector.create(

            evaluation

        )



        return {


            "approved":

                False,


            "evaluation":

                evaluation,


            "actions":

                actions

        }

"""
OM Correction Planner

Creates improvement actions.
"""




class CorrectionPlanner:



    def create(

        self,

        evaluation:dict

    ) -> list[str]:


        actions=[]



        for issue in evaluation.get(
            "issues",
            []
        ):


            if "empty" in issue:

                actions.append(
                    "Generate complete response"
                )


            if "short" in issue:

                actions.append(
                    "Add more explanation"
                )



        if not actions:

            actions.append(
                "Improve reasoning quality"
            )



        return actions

